+.tasks span { overflow-wrap: anywhere; min-width: 0; }
+.tasks input { flex-shrink: 0; width: 20px; height: 20px; }
 [role="alert"] { color: #a32121; }
 @media (max-width: 600px) { main { margin: 16px; padding: 20px; } form { grid-template-columns: 1fr; } }

